            aIngress = (RotL64(aFuseLaneB[((aIndex + 18261U)) & S_BLOCK1], 58U) ^ RotL64(aWaterLaneD[((aIndex + 16464U)) & S_BLOCK1], 3U));
            aIngress ^= (RotL64(pSnowLaneD[((aIndex + 20129U)) & S_BLOCK1], 19U) ^ RotL64(pSnowLaneC[((S_BLOCK1 - aIndex + 21739U)) & S_BLOCK1], 43U));
            aIngress = TwistMix64::DiffuseA(aIngress);
            //
            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 16951U)) & S_BLOCK1], 6U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 18676U)) & S_BLOCK1], 51U));
            aCross ^= RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 18597U)) & S_BLOCK1], 23U);
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aCarry, 27U) + RotL64(aPrevious, 43U)) ^ (RotL64(aCross, 13U) ^ RotL64(aIngress, 56U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterF = (aWandererB + RotL64(aIngress, 35U)) + 0x0DDCB3C63158D981ULL;
            aOrbiterI = ((aWandererI + RotL64(aCross, 11U)) + RotL64(aCarry, 37U)) + 0xA0BF0D1611D5133FULL;
            aOrbiterB = ((aWandererE + RotL64(aScatter, 41U)) + 0xCD2B8C1BE097B734ULL) + aTwistOrbiterAssignSaltE[((aIndex + 13U)) & S_SALT1];
            aOrbiterD = (aWandererH + RotL64(aPrevious, 18U)) + 0x42178DF6AB6DC448ULL;
            aOrbiterG = ((aWandererG + RotL64(aScatter, 29U)) + RotL64(aCarry, 3U)) + 0xC5ADC4A716C8295EULL;
            aOrbiterK = (aWandererF + RotL64(aPrevious, 51U)) + 0xC8870CC79FCE149CULL;
            aOrbiterA = (((aWandererA + RotL64(aIngress, 5U)) + RotL64(aCarry, 21U)) + 0xA41E383CE67ED043ULL) + aTwistOrbiterAssignSaltB[((aIndex + 21U)) & S_SALT1];
            //
            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0x80EE9FC1E472BCE9ULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0xE06E069F25D55138ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x4106B9506881EB81ULL), 19U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x09B31E9CB740AF48ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0xE60C4AE147326E0EULL;
            aOrbiterI = RotL64((aOrbiterI * 0xE7602E0718452AF1ULL), 5U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0x3F8D31309CB227BCULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0xAECD94636B3495DAULL;
            aOrbiterF = RotL64((aOrbiterF * 0xE4F2F0765376EBEFULL), 51U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterA) + 0x937D4B19A9D0783DULL) + aTwistOrbiterUpdateSaltE[((aIndex + 14U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0xFAC75A227916A1AAULL;
            aOrbiterG = RotL64((aOrbiterG * 0x9FCCFC6E4F089965ULL), 37U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterG) + 0x99A08ECF61A598BBULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterA) ^ 0xABA8AEC9659CEC27ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 17U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x097AA631994D80A9ULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x4407AC9056457282ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x35FC15E9BB1F5F45ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x08F49B6A3382871FULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0xA2A3A3F816CB03A3ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0x3E1D659C2F3A913FULL;
            aOrbiterK = RotL64((aOrbiterK * 0xC21F569843B4DDB7ULL), 43U);
            //
            aIngress = aOrbiterF ^ RotL64(aOrbiterA, 5U);
            aIngress = aIngress + (RotL64(aOrbiterI, 41U) ^ aOrbiterK);
            aIngress = aIngress + (RotL64(aOrbiterD, 27U) ^ aOrbiterG);
            aIngress = aIngress + RotL64(aOrbiterB, 13U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererA = aWandererA + ((RotL64(aCross, 46U) + aOrbiterI) + RotL64(aOrbiterD, 14U));
            aWandererE = aWandererE ^ (((RotL64(aScatter, 57U) + RotL64(aOrbiterB, 51U)) + aOrbiterK) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 7U)) & S_SALT1]);
            aWandererI = aWandererI + (((RotL64(aIngress, 19U) + RotL64(aOrbiterG, 57U)) + aOrbiterK) + RotL64(aCarry, 37U));
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 27U) + RotL64(aOrbiterB, 3U)) + aOrbiterA);
