            aWandererG = aWandererG ^ (((RotL64(aPrevious, 35U) + aOrbiterF) + RotL64(aOrbiterB, 29U)) + aTwistWandererUpdateSaltB[((aIndex + 27U)) & S_SALT1]);
            aWandererB = aWandererB + ((RotL64(aCross, 5U) + RotL64(aOrbiterK, 37U)) + aOrbiterA);
