            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 26426U)) & S_BLOCK1], 51U) ^ RotL64(aWaterLaneC[((S_BLOCK1 - aIndex + 28053U)) & S_BLOCK1], 26U));
            aCross ^= RotL64(aSource[((aIndex + 30107U)) & S_BLOCK1], 35U);
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aIngress, 51U) ^ RotL64(aCarry, 20U)) + (RotL64(aCross, 5U) + RotL64(aPrevious, 39U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterG = ((aWandererA + RotL64(aCross, 21U)) + RotL64(aCarry, 53U)) + 0x22D6A56EA4D15293ULL;
            aOrbiterE = ((aWandererD + RotL64(aScatter, 40U)) + 0xA78F9E198639D098ULL) + aTwistOrbiterAssignSaltA[((aIndex + 24U)) & S_SALT1];
            aOrbiterD = ((aWandererH + RotL64(aPrevious, 3U)) + RotL64(aCarry, 11U)) + 0xE0B12FD135ACDFAAULL;
            aOrbiterH = ((aWandererI + RotL64(aIngress, 47U)) + RotL64(aCarry, 41U)) + 0x3943B208B126A346ULL;
            aOrbiterC = (aWandererE + RotL64(aScatter, 57U)) + 0x0AAF239973695FCFULL;
            aOrbiterF = ((aWandererC + RotL64(aIngress, 11U)) + 0xBF6F028518EE5DE6ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterK = (aWandererJ + RotL64(aCross, 27U)) + 0x29D3DC108B80A31BULL;
            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x27289E1EA0377274ULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x0691E65B2E940425ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x36B8CF4FC296E65DULL), 19U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0x270C466CE8720846ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 27U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0x439481F680B8EEAFULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x1F44634604C09811ULL), 57U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0xC0AF8B6353DBE66CULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0x44FC4BE9F8DC4830ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xCC2759F8426F9CC1ULL), 5U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x98F763D1845724E5ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x0D5968622DA80B64ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x8324087D901D8D3DULL), 29U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0xA0E320CFCC17084FULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0xFB633504BA852E35ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x244D9E372E452913ULL), 51U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0xA589E0831F1328C3ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0x9684237B899B98D4ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xFA60F8361E5F7913ULL), 41U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0xCC4D3EA82502F04FULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x5443A0F44EDA5F0FULL;
            aOrbiterC = RotL64((aOrbiterC * 0x3F48C960E2C129DBULL), 11U);
            //
            aIngress = RotL64(aOrbiterC, 28U) ^ aOrbiterE;
