            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterG, 43U));
            aIngress = aIngress + RotL64(aOrbiterK, 35U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererH = aWandererH ^ (((RotL64(aPrevious, 60U) + RotL64(aOrbiterH, 23U)) + aOrbiterE) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 19U)) & S_SALT1]);
            aWandererC = aWandererC + ((((RotL64(aIngress, 21U) + aOrbiterE) + RotL64(aOrbiterK, 5U)) + RotL64(aCarry, 11U)) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 8U)) & S_SALT1]);
            aWandererI = aWandererI ^ ((RotL64(aScatter, 41U) + aOrbiterC) + RotL64(aOrbiterF, 13U));
            aWandererA = aWandererA + ((RotL64(aCross, 5U) + RotL64(aOrbiterK, 44U)) + aOrbiterF);
