            aWandererD = aWandererD + (((RotL64(aScatter, 53U) + aOrbiterD) + RotL64(aOrbiterG, 51U)) + RotL64(aCarry, 39U));
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 35U) + aOrbiterD) + RotL64(aOrbiterH, 57U));
