    std::uint64_t *aTwistOrbiterUpdateSaltB = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltB;
    std::uint64_t *aTwistOrbiterUpdateSaltC = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltC;
    std::uint64_t *aTwistOrbiterUpdateSaltD = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltD;
    std::uint64_t *aTwistOrbiterUpdateSaltE = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltE;
    std::uint64_t *aTwistOrbiterUpdateSaltF = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltF;
    std::uint64_t *aTwistWandererUpdateSaltA = pWorkSpace->mDomainBundle.mTwistSalts.mWandererUpdate.mSaltA;
    std::uint64_t *aTwistWandererUpdateSaltB = pWorkSpace->mDomainBundle.mTwistSalts.mWandererUpdate.mSaltB;
    std::uint64_t *aTwistWandererUpdateSaltC = pWorkSpace->mDomainBundle.mTwistSalts.mWandererUpdate.mSaltC;
