            aOrbiterG = (aWandererC + RotL64(aIngress, 5U)) + 0xAE65A830B8616A6AULL;
            aOrbiterD = ((aWandererB + RotL64(aScatter, 43U)) + RotL64(aCarry, 47U)) + 0x83C21FCD7E06C264ULL;
            aOrbiterC = ((aWandererG + RotL64(aCross, 14U)) + 0x6143767E6A60818CULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0xD33DF6B0E8B6FC40ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x9AF7198A0FBEE1A3ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xD8D93CD30D0BCD1DULL), 57U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterH) + 0x6D47BE0A70719441ULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterF) ^ 0x5F0D013BDB6707D1ULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xF8B322B9F901CD43ULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0xD43E8CC0F4AA76CBULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x33861D0E6E20AAB4ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x6C726BA57C2929CFULL), 21U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0xFC8A51610CDFD1E8ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterE) ^ 0x176A9DB30B92AB49ULL) ^ aKeyRotateOrbiterUpdateSaltC[((aIndex + 9U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x2198F9ADB43DF997ULL), 5U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xA6F677B739121789ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0xC1CB0E94924859F7ULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 7U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x3A711059E37D0D95ULL), 27U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x561C859F09F88B9EULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0x86EAD26A078F4179ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xE37AC2073733D2A9ULL), 43U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x1FC2B931AC72C28BULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0x31C722211C5E5050ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x0AD3B486A09711EFULL), 51U);
            //
            aIngress = RotL64(aOrbiterC, 13U) ^ aOrbiterF;
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterH, 3U));
            aIngress = aIngress + (RotL64(aOrbiterB, 41U) ^ aOrbiterG);
            aIngress = aIngress + RotL64(aOrbiterE, 35U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererG = aWandererG ^ (((RotL64(aCross, 51U) + aOrbiterB) + RotL64(aOrbiterE, 41U)) + aKeyRotateWandererUpdateSaltE[(((31U - aIndex) + 5U)) & S_SALT1]);
            aWandererB = aWandererB + ((((RotL64(aIngress, 41U) + aOrbiterC) + RotL64(aOrbiterG, 57U)) + RotL64(aCarry, 27U)) + aKeyRotateWandererUpdateSaltA[((aIndex + 13U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 27U) + aOrbiterD) + RotL64(aOrbiterC, 35U));
            aWandererD = aWandererD + (((RotL64(aScatter, 35U) + aOrbiterG) + RotL64(aOrbiterB, 3U)) + RotL64(aCarry, 51U));
            aWandererE = aWandererE ^ ((RotL64(aIngress, 3U) + RotL64(aOrbiterG, 47U)) + aOrbiterD);
            aWandererC = aWandererC + ((RotL64(aPrevious, 12U) + RotL64(aOrbiterF, 26U)) + aOrbiterH);
            aWandererJ = aWandererJ ^ ((RotL64(aCross, 57U) + aOrbiterH) + RotL64(aOrbiterE, 19U));
            //
            aCarry = aCarry + (RotL64(aWandererH, 57U) ^ aWandererJ);
