            aCross = (RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 28562U)) & S_BLOCK1], 35U) ^ RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 32253U)) & S_BLOCK1], 27U));
            aCross ^= (RotL64(aKeyRowReadA[(((2047U - aIndex) + 27981U)) & W_KEY1], 4U) ^ RotL64(aSoilLaneD[((S_BLOCK1 - aIndex + 26962U)) & S_BLOCK1], 47U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aIngress, 21U) ^ RotL64(aCross, 37U)) ^ (RotL64(aPrevious, 5U) + RotL64(aCarry, 54U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterK = (aWandererF + RotL64(aIngress, 53U)) + 0x9ABCC439367D07C1ULL;
            aOrbiterA = ((aWandererC + RotL64(aScatter, 29U)) + RotL64(aCarry, 11U)) + 0xBD196454D678DC61ULL;
            aOrbiterH = ((aWandererG + RotL64(aCross, 20U)) + 0x58EBE4D146A4BA26ULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterB = ((aWandererB + RotL64(aPrevious, 37U)) + RotL64(aCarry, 37U)) + 0x843E9DB466E72399ULL;
            aOrbiterC = (aWandererH + RotL64(aScatter, 5U)) + 0x6C1EE14ECC1B8798ULL;
            aOrbiterE = (aWandererK + RotL64(aPrevious, 13U)) + 0x0359D1C6ACE15B1AULL;
            aOrbiterI = (((aWandererI + RotL64(aCross, 43U)) + RotL64(aCarry, 51U)) + 0x1DB15C6142B409BFULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 16U)) & S_SALT1];
            //
            aOrbiterK = ((aOrbiterK + aOrbiterA) + 0x49919FAF5E652BE3ULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 13U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterK) ^ 0x32F1990B49B23A3DULL) ^ aKeyRotateOrbiterUpdateSaltA[((aIndex + 28U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x0D0184E2DF9A0C7DULL), 29U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0xDF3062D6FDDEF978ULL) + aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x7D555A7365457923ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x80FD26AB77C2963DULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x93C7237E6903CF26ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0xEA54A905358D1796ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x16673BFBDBC630A9ULL), 13U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0x404BA5E730AF7110ULL) + aKeyRotateOrbiterUpdateSaltF[((aIndex + 11U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x6248692FD0CB6B57ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x190966C617278E73ULL), 21U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x9C0CCC4F19F28433ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0x4C1AC829E63274BEULL;
            aOrbiterA = RotL64((aOrbiterA * 0x7DC746C29BB810A5ULL), 41U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0xA437665B48544EF2ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x5D102D79F047D23EULL;
            aOrbiterK = RotL64((aOrbiterK * 0x37F04D1B8593EBA9ULL), 51U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0x21A10CC847022F03ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x81E4249ED756D406ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x791C9656C411DF27ULL), 57U);
            //
            aIngress = aOrbiterH ^ RotL64(aOrbiterB, 11U);
            aIngress = aIngress + (RotL64(aOrbiterA, 35U) ^ aOrbiterI);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterK, 41U));
            aIngress = aIngress + RotL64(aOrbiterE, 60U);
