            //
            aWandererF = aWandererF + (((RotL64(aScatter, 41U) + RotL64(aOrbiterC, 29U)) + aOrbiterH) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 12U)) & S_SALT1]);
            aWandererB = aWandererB ^ (((RotL64(aIngress, 47U) + aOrbiterA) + RotL64(aOrbiterB, 13U)) + aKeyRotateWandererUpdateSaltF[(((31U - aIndex) + 9U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aCross, 27U) + RotL64(aOrbiterH, 48U)) + aOrbiterK);
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 3U) + RotL64(aOrbiterC, 3U)) + aOrbiterB);
            aWandererK = aWandererK + (((RotL64(aScatter, 11U) + aOrbiterE) + RotL64(aOrbiterI, 21U)) + RotL64(aCarry, 47U));
            aWandererC = aWandererC ^ ((RotL64(aIngress, 35U) + RotL64(aOrbiterE, 35U)) + aOrbiterC);
