            aScatter = (RotL64(aCross, 5U) + RotL64(aIngress, 39U)) ^ (RotL64(aCarry, 51U) + RotL64(aPrevious, 26U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterI = ((aWandererH + RotL64(aCross, 14U)) + RotL64(aCarry, 51U)) + 0x90F08BC8610F2A3FULL;
            aOrbiterA = (aWandererG + RotL64(aIngress, 3U)) + 0xBB93AB73C5E2A265ULL;
            aOrbiterJ = ((aWandererE + RotL64(aScatter, 5U)) + RotL64(aCarry, 13U)) + 0x035CD67EF4B43681ULL;
            aOrbiterE = ((aWandererF + RotL64(aPrevious, 29U)) + 0xAF1AC475161945C4ULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 28U)) & S_SALT1];
            aOrbiterB = (aWandererK + RotL64(aIngress, 37U)) + 0x76EFC5239FDC27F1ULL;
            aOrbiterK = (aWandererJ + RotL64(aScatter, 52U)) + 0xE21885F8A9E1C062ULL;
            aOrbiterG = (aWandererB + RotL64(aPrevious, 19U)) + 0x0EF8B06A9ACBDAE1ULL;
            aOrbiterC = ((aWandererA + RotL64(aCross, 11U)) + 0x4B1A0B9D82272607ULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterD = (aWandererI + RotL64(aScatter, 39U)) + 0xF92B08ADD1DAC671ULL;
            aOrbiterH = ((aWandererD + RotL64(aIngress, 57U)) + RotL64(aCarry, 27U)) + 0xD8D54A6D48CA4AD4ULL;
            aOrbiterF = (aWandererC + RotL64(aPrevious, 41U)) + 0x3A5508974B442BC7ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x6782D585CF6ED30DULL;
