            aOrbiterI = RotL64((aOrbiterI * 0x3CC3610929C13D5DULL), 11U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0xB01790860F32872AULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x6230C72038D5D5BAULL;
            aOrbiterK = RotL64((aOrbiterK * 0xB79BE6EBEA4BCF55ULL), 47U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterC) + 0x63B363519831CF9BULL;
