            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0xCC9F1322DF9BBBAAULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0xE54FB97E0A85E894ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x23A9EBE947C339C5ULL), 51U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0x9AD20C4A9DEADD67ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 3U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0xC414DB9761375133ULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 16U)) & S_SALT1];
