            //
            aOrbiterB = (aWandererG + RotL64(aIngress, 11U)) + 0x2F97E07CD1FC6BE9ULL;
            aOrbiterK = (((aWandererI + RotL64(aScatter, 21U)) + RotL64(aCarry, 53U)) + 0x6E7DAAF2A427488CULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 4U)) & S_SALT1];
            aOrbiterF = ((aWandererE + RotL64(aPrevious, 39U)) + RotL64(aCarry, 41U)) + 0x736E56AE267B5915ULL;
            aOrbiterE = (aWandererF + RotL64(aCross, 29U)) + 0x02591A465E6636E5ULL;
            aOrbiterD = ((aWandererK + RotL64(aScatter, 60U)) + 0x219BE2E9D167C2F8ULL) + aKeyRotateOrbiterAssignSaltC[((aIndex + 27U)) & S_SALT1];
            aOrbiterG = ((aWandererD + RotL64(aCross, 51U)) + RotL64(aCarry, 5U)) + 0xEC467C79A748DD0FULL;
