            //
            aOrbiterB = ((aOrbiterB + aOrbiterK) + 0x03822EB676C1F896ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 26U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x2A9EC2D72A16304CULL;
            aOrbiterF = RotL64((aOrbiterF * 0x049233269AFD9DF3ULL), 35U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x821A251EC84D5A65ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0x4DD86F7CEFC1EF24ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xEC3317050A2D53C3ULL), 29U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x6A80FC0602A7C090ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0x0AABA40C7633279CULL) ^ aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xBDB1305A4CF2511BULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0x0530C63C3A35A656ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0x146E130153786329ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x93C18C8E75C278CBULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x193DD6316A749685ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0x63A0E09926F5A1F0ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xA9E09DE0CACE6F27ULL), 5U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x4EC89CE899B7B868ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterK) ^ 0xDCBF6E47D8E1D0DAULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
