            aWandererE = aWandererE ^ (((RotL64(aCross, 13U) + RotL64(aOrbiterH, 35U)) + aOrbiterF) + aKeyRotateWandererUpdateSaltF[((aIndex + 10U)) & S_SALT1]);
            aWandererJ = aWandererJ + ((RotL64(aIngress, 5U) + RotL64(aOrbiterH, 13U)) + aOrbiterI);
