            aOrbiterD = RotL64((aOrbiterD * 0x52FE407D14A679D5ULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x6BCC5A93B711A788ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterI) ^ 0xBFB4E9E28CCD8137ULL) ^ aKeySpawnOrbiterUpdateSaltD[((aIndex + 29U)) & S_SALT1];
