            //
            aIngress = (RotL64(aKineticLaneA[((aIndex + 9834U)) & S_BLOCK1], 13U) ^ RotL64(aAetherLaneC[((aIndex + 9695U)) & S_BLOCK1], 38U));
            aIngress ^= (RotL64(aKeyRowReadB[((aIndex + 9787U)) & W_KEY1], 5U) ^ RotL64(aWindLaneA[((aIndex + 7351U)) & S_BLOCK1], 21U));
            aIngress = TwistMix64::DiffuseC(aIngress);
            //
            aCross = (RotL64(aAetherLaneA[((S_BLOCK1 - aIndex + 9592U)) & S_BLOCK1], 13U) ^ RotL64(aAetherLaneD[((S_BLOCK1 - aIndex + 6319U)) & S_BLOCK1], 53U));
            aCross ^= (RotL64(aVaporLaneA[((S_BLOCK1 - aIndex + 7213U)) & S_BLOCK1], 21U) ^ RotL64(aVaporLaneD[((aIndex + 6653U)) & S_BLOCK1], 38U));
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aPrevious, 6U) + RotL64(aCarry, 39U)) ^ (RotL64(aCross, 53U) ^ RotL64(aIngress, 23U));
