            aOrbiterC = RotL64((aOrbiterC * 0xCDD2734C69630BC9ULL), 43U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0xF7C13217AADE7322ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0x353C132191F2EDEEULL;
            aOrbiterE = RotL64((aOrbiterE * 0xB3073C2C824E4633ULL), 29U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterI) + 0xE4146A62F5CC968DULL) + aKeySpawnOrbiterUpdateSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x8D73D6C5B20A8285ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x524DB053F59C1FC5ULL), 23U);
