            aWandererK = aWandererK ^ (((RotL64(aPrevious, 37U) + RotL64(aOrbiterD, 29U)) + aOrbiterJ) + aKeySpawnWandererUpdateSaltA[((aIndex + 25U)) & S_SALT1]);
