            aIngress ^= (RotL64(aKeyRowReadB[((aIndex + 14838U)) & W_KEY1], 42U) ^ RotL64(aKineticLaneD[((S_BLOCK1 - aIndex + 12078U)) & S_BLOCK1], 29U));
            aIngress = TwistMix64::DiffuseB(aIngress);
