            aCross = (RotL64(aCelestialLaneA[((S_BLOCK1 - aIndex + 15181U)) & S_BLOCK1], 23U) ^ RotL64(aCelestialLaneD[((S_BLOCK1 - aIndex + 8362U)) & S_BLOCK1], 60U));
