            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0x2D755AED8464629DULL) + aKeySpawnOrbiterUpdateSaltC[((aIndex + 7U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x58C76C5B73AA9F1CULL;
            aOrbiterB = RotL64((aOrbiterB * 0xF45491597BC19A61ULL), 23U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0xBEDE9020D1218F34ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x37D98603213C6F47ULL;
