            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0xDF69D8DD58E3494BULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x5ED3495ED393F070ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xDD36B05275AC7747ULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0xE9561F8301D9770DULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0xFB0E503128126E0DULL) ^ aKeySpawnOrbiterUpdateSaltD[(((31U - aIndex) + 22U)) & S_SALT1];
